select.dynamic:
SELECT /** 판매인력 자격내역 테이블 건수 조회 수행한다 : countCmbsSalesHmrsMgt */ count(사용자번호) FROM ( SELECT KR31.사용자번호 FROM INST1.TSKEEKR31 KR31 WHERE KR31.그룹회사코드 = #groupCoCd# AND KR31.사용자번호 = #empno# AND KR31.자본시장자격증코드 = #qlcrCd#
AND ( (#qlcrValdYmd# BETWEEN KR31.자격증유효시작년월일 AND KR31.자격증유효종료년월일) OR (#qlcrValdEndYmd# BETWEEN KR31.자격증유효시작년월일 AND KR31.자격증유효종료년월일) OR (KR31.자격증유효종료년월일 > #qlcrValdEndYmd#) )
)
